2	import type { Metadata } from "next";
3	import { ComparisonTemplate } from "@/components/marketing/comparisontemplate/ComparisonTemplate";
4	import { COMPETITOR, FAQ } from "@/components/marketing/comparisontemplate/data";
5	import { CompetitorLogo } from "@/components/marketing/CompetitorLogo";
6	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
7	import { FaqJsonLd, ProductJsonLd } from "@/components/marketing/StructuredData";
8	import { getVpsPriceBand } from "@/lib/vps-price-band";
9	import { db } from "@/lib/db";
10	import Link from "next/link";
11	
12	const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
13	const PATH = "/vps-vs-digitalocean";
14	
15	export const metadata: Metadata = {
16	  title: "Nxeon vs DigitalOcean — an honest VPS comparison",
17	  description:
18	    "How Nxeon compares to DigitalOcean for cloud VPS hosting: pricing, NVMe storage, game servers, dedicated IPs, free managed migration and where each one is the better fit — compared honestly, row by row.",
19	  alternates: { canonical: PATH },
20	  openGraph: {
21	    type: "article",
22	    title: "Nxeon vs DigitalOcean — an honest VPS comparison",
23	    description:
24	      "Pricing, NVMe storage, game servers, dedicated IPs and a free managed migration compared. An honest look at where each provider wins.",
25	    url: `${APP_URL}${PATH}`,
26	    images: [{ url: `${APP_URL}/logo.png` }],
27	  },
28	};
29	
30	// Prices track the live catalogue — see lib/vps-price-band.ts. Set force-dynamic
31	// so the DB-fed band and Product schema are read on every request, same as the
32	// rest of the comparison surface.
33	export const dynamic = "force-dynamic";
34	
35	export default async function VpsVsDigitalOcean() {
36	  let fromLabel: string | undefined;
37	  let plans: Array<{ name: string; priceCents: number }> = [];
38	  try {
39	    const [band, planRows] = await Promise.all([
40	      getVpsPriceBand(),
41	      db.plan.findMany({
42	        where: { active: true },
43	        orderBy: { priceCents: "asc" },
44	        select: { name: true, priceCents: true },
45	      }),
46	    ]);
47	    fromLabel = band?.fromLabel;
48	    plans = planRows;
49	  } catch {
50	    /* DB unavailable — render without a price badge or Product schema */
51	  }
52	
53	  return (
54	    <>
55	      <FaqJsonLd items={FAQ} />
56	      {plans.length > 0 ? <ProductJsonLd plans={plans} /> : null}
57	      <ComparisonTemplate
58	        nxeonLogo={<CompetitorLogo slug="nxeon" name="Nxeon" size={26} />}
59	        competitorLogo={<CompetitorLogo slug={COMPETITOR.slug} name={COMPETITOR.name} size={26} />}
60	        reviewBadges={<ReviewBadges />}
61	        fromLabel={fromLabel}
62	      />
63	      <div className="rail py-10 text-center">
64	        <p className="text-sm text-slate-400">
65	          Already decided?{" "}
66	          <Link href="/migrate-from-digitalocean" className="font-medium text-brand-300 hover:text-brand-200">
67	            See exactly how we move you over free →
68	          </Link>
69	        </p>
70	      </div>
71	    </>
72	  );
73	}
74	--- ComparisonTemplate.tsx ---
75	"use client";
76	
77	/**
78	 * PREVIEW TEMPLATE 1 — Competitor "vs" comparison page (Nxeon vs DigitalOcean).
79	 *
80	 * The centrepiece is a credible, grouped head-to-head table (a real <table> for
81	 * SEO + AI-assistant citation; a stacked card view on mobile) built to the same
82	 * standard as the live comparison surface (CompareTable + ComparePageLayout):
83	 * rows grouped by pricing / specs / support / platform, real competitor logos in
84	 * the column headers, a DB-fed Nxeon "from" price, an HONEST three-way verdict
85	 * (Nxeon wins · even · DigitalOcean wins) and a trademark/accuracy disclaimer.
86	 * Around it: an honest animated scoreboard that counts straight from the table
87	 * (competitor wins included), a "why teams switch" narrative, a free-migration
88	 * CTA that reuses the live MigrationScreens animation, the real third-party
89	 * ReviewBadges strip, a straight-answer decision grid and an FAQ.
90	 *
91	 * Net-new, preview-only. This is a "use client" component, so the server-only
92	 * bits it needs — the CompetitorLogo marks and the async ReviewBadges — are
93	 * rendered by the server page (app/(marketing)/preview/comparison/page.tsx) and
94	 * passed in as props. Every motion path respects prefers-reduced-motion. Reuses
95	 * only shared brand primitives (.rail / .card / .btn-deploy / grad-text /
96	 * eyebrow …) and the `pv-*` keyframes already in globals.css — adds no CSS.
97	 */
98	
99	import Link from "next/link";
100	import { useEffect, useRef, useState, type ReactNode } from "react";
101	import { MigrationScreens } from "@/components/marketing/showcase/MigrationScreens";
102	import {
103	  IconCheck,
104	  IconBolt,
105	  IconShield,
106	  IconBackup,
107	  IconSupport,
108	} from "@/components/marketing/icons";
109	import {
110	  COMPETITOR,
111	  COMPARE_GROUPS,
112	  SCORE,
113	  SWITCH_REASONS,
114	  CHOOSE_NXEON,
115	  CHOOSE_OTHER,
116	  REVIEWS,
117	  FAQ,
118	  DISCLAIMER,
119	  type CompareRow,
120	  type CompareGroup,
121	  type SwitchReason,
122	  type Verdict,
123	} from "./data";
124	
125	export type ComparisonTemplateProps = {
126	  /** Nxeon mark, pre-rendered on the server (CompetitorLogo slug="nxeon"). */
127	  nxeonLogo?: ReactNode;
128	  /** Competitor mark, pre-rendered on the server (CompetitorLogo slug=…). */
129	  competitorLogo?: ReactNode;
130	  /** Real third-party review strip (ReviewBadges), rendered on the server. */
131	  reviewBadges?: ReactNode;
132	  /** DB-fed Nxeon entry price, e.g. "$6.49/mo" — shown as a header badge. */
133	  fromLabel?: string;
134	};
135	
136	/* ── self-contained motion hooks ─────────────────────────────────────────── */
137	function usePrefersReducedMotion() {
138	  const [reduced, setReduced] = useState(false);
139	  useEffect(() => {
140	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
141	    if (!mq) return;
142	    setReduced(mq.matches);
143	    const on = () => setReduced(mq.matches);
144	    mq.addEventListener?.("change", on);
145	    return () => mq.removeEventListener?.("change", on);
146	  }, []);
147	  return reduced;
148	}
149	
150	function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
151	  const ref = useRef<T | null>(null);
152	  const [seen, setSeen] = useState(false);
153	  useEffect(() => {
154	    const el = ref.current;
155	    if (!el || typeof IntersectionObserver === "undefined") {
156	      setSeen(true);
157	      return;
158	    }
159	    const io = new IntersectionObserver(
160	      ([e]) => {
161	        if (e.isIntersecting) {
162	          setSeen(true);
163	          io.disconnect();
164	        }
165	      },
166	      { threshold: 0.15, rootMargin: margin },
167	    );
168	    io.observe(el);
169	    return () => io.disconnect();
170	  }, [margin]);
171	  return { ref, seen };
172	}
173	
174	function useCountUp(target: number, active: boolean, duration = 1000, reduced = false) {
175	  const [val, setVal] = useState(reduced ? target : 0);
176	  useEffect(() => {
177	    if (!active) return;
178	    if (reduced) {
179	      setVal(target);
180	      return;
181	    }
182	    let raf = 0;
183	    const start = performance.now();
184	    const tick = (now: number) => {
185	      const t = Math.min(1, (now - start) / duration);
186	      const eased = 1 - Math.pow(1 - t, 3);
187	      setVal(Math.round(target * eased));
188	      if (t < 1) raf = requestAnimationFrame(tick);
189	    };
190	    raf = requestAnimationFrame(tick);
191	    return () => cancelAnimationFrame(raf);
192	  }, [target, active, duration, reduced]);
193	  return val;
194	}
195	
196	/* ── atoms ───────────────────────────────────────────────────────────────── */
197	const REASON_ICON: Record<SwitchReason["icon"], (p: { size?: number; className?: string }) => React.ReactElement> = {
198	  shield: IconShield,
199	  backup: IconBackup,
200	  support: IconSupport,
201	  bolt: IconBolt,
202	};
203	
204	/** Text fallback marks, used only if the server didn't pass real logos. */
205	function NxeonMark({ className = "" }: { className?: string }) {
206	  return <span className={`font-semibold tracking-tight ${className}`}>Nxeon</span>;
207	}
208	function CompetitorMark({ className = "" }: { className?: string }) {
209	  return <span className={`font-semibold tracking-tight ${className}`}>{COMPETITOR.name}</span>;
210	}
211	
212	/* ── verdict markers ─────────────────────────────────────────────────────── */
213	/** Cyan check — a genuine Nxeon win. */
214	function WinCheck({ shown = true }: { shown?: boolean }) {
215	  return (
216	    <span
217	      className="inline-flex h-6 w-6 flex-none items-center justify-center rounded-full bg-accent-cyan/15 text-accent-cyan ring-1 ring-accent-cyan/30 transition-all duration-500"
218	      style={{ transform: shown ? "scale(1)" : "scale(0.4)", opacity: shown ? 1 : 0 }}
219	      aria-hidden
220	    >
221	      <IconCheck size={15} />
222	    </span>
223	  );
224	}
225	
226	/** Slate check — the other side genuinely leads this row (honest). */
227	function LeadCheck() {
228	  return (
229	    <span
230	      className="inline-flex h-6 w-6 flex-none items-center justify-center rounded-full bg-white/[0.06] text-slate-300 ring-1 ring-white/10"
231	      aria-hidden
232	    >
233	      <IconCheck size={15} />
234	    </span>
235	  );
236	}
237	
238	/** Neutral dot — present, but not the differentiator on this row. */
239	function NeutralDot() {
240	  return (
241	    <span
242	      className="inline-flex h-6 w-6 flex-none items-center justify-center rounded-full bg-white/[0.03] text-slate-500 ring-1 ring-white/10"
243	      aria-hidden
244	    >
245	      <span className="block h-[2px] w-2.5 rounded-full bg-slate-500" />
246	    </span>
247	  );
248	}
249	
250	function nxeonMarker(v: Verdict, shown: boolean): React.ReactElement {
251	  if (v === "win") return <WinCheck shown={shown} />;
252	  return <NeutralDot />;
253	}
254	function otherMarker(v: Verdict): React.ReactElement | null {
255	  if (v === "other") return <LeadCheck />;
256	  if (v === "tie") return <NeutralDot />;
257	  return null;
258	}
259	
260	/** Small "who leads" pill for the feature cell / mobile card. */
261	function VerdictPill({ v }: { v: Verdict }) {
262	  if (v === "win")
263	    return (
264	      <span className="inline-flex items-center gap-1 rounded-full bg-accent-cyan/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-accent-cyan">
265	        <IconCheck size={11} /> Nxeon wins
266	      </span>
267	    );
268	  if (v === "other")
269	    return (
270	      <span className="inline-flex items-center rounded-full bg-white/[0.06] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-slate-300">
271	        {COMPETITOR.name} wins
272	      </span>
273	    );
274	  return (
275	    <span className="inline-flex items-center rounded-full bg-white/[0.04] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-slate-500">
276	      Even
277	    </span>
278	  );
279	}
280	
281	/* ── honest animated scoreboard (hero visual) ────────────────────────────── */
282	function ScoreBoard() {
283	  const reduced = usePrefersReducedMotion();
284	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
285	  const wins = useCountUp(SCORE.nxeonWins, seen, 900, reduced);
286	  const ties = useCountUp(SCORE.ties, seen, 1050, reduced);
287	  const others = useCountUp(SCORE.otherWins, seen, 1200, reduced);
288	
289	  return (
290	    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
291	      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/85 p-6 shadow-2xl shadow-black/50 backdrop-blur-xl sm:p-7">
292	        <div
293	          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
294	          style={{ background: "radial-gradient(45% 45% at 82% 0%, rgba(34,211,238,0.20), transparent 70%)" }}
295	          aria-hidden
296	        />
297	        <div className="flex items-center justify-between">
298	          <span className="inline-flex items-center gap-2 rounded-full bg-emerald-500/12 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
299	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
300	            head-to-head
301	          </span>
302	          <span className="font-mono text-[11px] uppercase tracking-widest text-slate-500">
303	            {SCORE.total} features compared
304	          </span>
305	        </div>
306	
307	        {/* three honest tallies — competitor wins counted, not hidden */}
308	        <div className="mt-6 grid grid-cols-3 gap-3">
309	          <div className="rounded-2xl border border-accent-cyan/25 bg-gradient-to-b from-accent-cyan/[0.10] to-transparent px-3 py-5 text-center">
310	            <p className="font-mono text-3xl font-bold tabular-nums text-accent-cyan sm:text-4xl">{wins}</p>
311	            <p className="mt-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-300">Nxeon wins</p>
312	          </div>
313	          <div className="rounded-2xl border border-white/[0.07] bg-white/[0.02] px-3 py-5 text-center">
314	            <p className="font-mono text-3xl font-bold tabular-nums text-slate-300 sm:text-4xl">{ties}</p>
315	            <p className="mt-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-500">Even</p>
316	          </div>
317	          <div className="rounded-2xl border border-white/[0.07] bg-white/[0.02] px-3 py-5 text-center">
318	            <p className="font-mono text-3xl font-bold tabular-nums text-slate-300 sm:text-4xl">{others}</p>
319	            <p className="mt-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-500">{COMPETITOR.name} wins</p>
320	          </div>
321	        </div>
322	
323	        <div className="mt-4 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-2.5 text-center text-[12px] leading-relaxed text-slate-400">
324	          Counted straight from the table below — including the rows where{" "}
325	          <span className="font-medium text-slate-300">{COMPETITOR.name}</span> honestly wins.
326	        </div>
327	      </div>
328	    </div>
329	  );
330	}
331	
332	/* ── the credible, grouped comparison table ──────────────────────────────── */
333	function ComparisonTable({
334	  nxeonLogo,
335	  competitorLogo,
336	  fromLabel,
337	}: {
338	  nxeonLogo?: ReactNode;
339	  competitorLogo?: ReactNode;
340	  fromLabel?: string;
341	}) {
342	  const { ref, seen } = useInViewOnce<HTMLDivElement>("0px 0px -8% 0px");
343	
344	  return (
345	    <div ref={ref}>
346	      {/* ── desktop: a real semantic table (SEO + AI citation) ───────────── */}
347	      <div className="hidden md:block">
348	        <div className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-900/60 p-2 backdrop-blur-md">
349	          {/* violet glow behind the Nxeon column */}
350	          <div
351	            className="pointer-events-none absolute inset-y-2 left-[26%] w-[40%] rounded-2xl"
352	            style={{
353	              background: "linear-gradient(180deg, rgba(111,71,245,0.10), rgba(34,211,238,0.04) 60%, transparent)",
354	              boxShadow: "inset 0 0 0 1px rgba(111,71,245,0.22)",
355	            }}
356	            aria-hidden
357	          />
358	          <table className="relative w-full border-separate border-spacing-0 text-sm">
359	            <thead>
360	              <tr>
361	                <th className="w-[26%] px-5 py-5 text-left align-bottom">
362	                  <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">Compared</span>
363	                </th>
364	                <th className="w-[40%] px-5 py-5 text-left align-bottom">
365	                  <span className="flex items-center gap-2">
366	                    {nxeonLogo ?? <NxeonMark className="text-xl text-white" />}
367	                    <span className="rounded-full bg-accent-cyan/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-accent-cyan">
368	                      managed
369	                    </span>
370	                  </span>
371	                  <span className="mt-2 block text-[11px] font-medium text-accent-cyan/80">
372	                    {fromLabel ? (
373	                      <>
374	                        from <span className="font-semibold text-accent-cyan">{fromLabel}</span> · first month free
375	                      </>
376	                    ) : (
377	                      "first month free"
378	                    )}
379	                  </span>
380	                </th>
381	                <th className="w-[34%] px-5 py-5 text-left align-bottom">
382	                  <span className="flex items-center">
383	                    {competitorLogo ?? <CompetitorMark className="text-lg text-slate-300" />}
384	                  </span>
385	                  <span className="mt-2 block text-[11px] font-medium text-slate-600">{COMPETITOR.kind}</span>
386	                </th>
387	              </tr>
388	            </thead>
389	            <tbody>
390	              {COMPARE_GROUPS.map((group) => (
391	                <TableGroup key={group.label} group={group} seen={seen} />
392	              ))}
393	            </tbody>
394	          </table>
395	        </div>
396	      </div>
397	
398	      {/* ── mobile: stacked comparison cards, grouped (no awkward h-scroll) ── */}
399	      <div className="space-y-6 md:hidden">
400	        {/* header marks so the reader knows the two sides */}
401	        <div className="flex items-center justify-between rounded-2xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 backdrop-blur-md">
402	          <span className="flex items-center gap-2">
403	            {nxeonLogo ?? <NxeonMark className="text-base text-white" />}
404	          </span>
405	          <span className="font-mono text-[11px] uppercase tracking-widest text-slate-600">vs</span>
406	          <span className="flex items-center">
407	            {competitorLogo ?? <CompetitorMark className="text-base text-slate-300" />}
408	          </span>
409	        </div>
410	        {COMPARE_GROUPS.map((group) => (
411	          <div key={group.label} className="space-y-3">
412	            <p className="px-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500">{group.label}</p>
413	            {group.rows.map((row, i) => (
414	              <MobileRowCard key={row.feature} row={row} seen={seen} index={i} />
415	            ))}
416	          </div>
417	        ))}
418	      </div>
419	
420	      <p className="mt-6 text-center text-[11px] leading-relaxed text-slate-600">{DISCLAIMER}</p>
421	    </div>
422	  );
423	}
424	
425	function TableGroup({ group, seen }: { group: CompareGroup; seen: boolean }) {
426	  return (
427	    <>
428	      <tr>
429	        <td colSpan={3} className="px-5 pb-2 pt-6">
430	          <span className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500">{group.label}</span>
431	        </td>
432	      </tr>
433	      {group.rows.map((row, i) => (
434	        <TableRow key={row.feature} row={row} seen={seen} index={i} />
435	      ))}
436	    </>
437	  );
438	}
439	
440	function TableRow({ row, seen }: { row: CompareRow; seen: boolean; index: number }) {
441	  const om = otherMarker(row.verdict);
442	  return (
443	    <tr className="group">
444	      {/* feature + honest note + who-leads pill */}
445	      <td className="border-t border-white/[0.06] px-5 py-4 align-top">
446	        <span className="block text-[13px] font-semibold text-white">{row.feature}</span>
447	        <span className="mt-1.5 block"><VerdictPill v={row.verdict} /></span>
448	        <span className="mt-1.5 block max-w-[24ch] text-[11px] leading-relaxed text-slate-500">{row.note}</span>
449	      </td>
450	      {/* Nxeon — emphasised */}
451	      <td className="border-t border-accent-cyan/15 px-5 py-4 align-top transition-colors group-hover:bg-white/[0.02]">
452	        <span className="flex items-start gap-2.5">
453	          {nxeonMarker(row.verdict, seen)}
454	          <span
455	            className={`text-[13px] leading-snug ${
456	              row.verdict === "win" ? "font-medium text-slate-100" : "text-slate-300"
457	            }`}
458	          >
459	            {row.nxeon}
460	          </span>
461	        </span>
462	      </td>
463	      {/* competitor — neutral, but credited when it leads */}
464	      <td className="border-t border-white/[0.06] px-5 py-4 align-top">
465	        <span className="flex items-start gap-2.5">
466	          {om ?? <span className="h-6 w-6 flex-none" aria-hidden />}
467	          <span
468	            className={`text-[13px] leading-snug ${
469	              row.verdict === "other" ? "font-medium text-slate-200" : "text-slate-400"
470	            }`}
471	          >
472	            {row.other}
473	          </span>
474	        </span>
475	      </td>
476	    </tr>
477	  );
478	}
479	
480	function MobileRowCard({ row, seen, index }: { row: CompareRow; seen: boolean; index: number }) {
481	  return (
482	    <div
483	      className="rounded-2xl border border-white/[0.07] bg-navy-900/60 p-4 backdrop-blur-md transition-all duration-500"
484	      style={{
485	        transitionDelay: `${index * 55}ms`,
486	        opacity: seen ? 1 : 0,
487	        transform: seen ? "translateY(0)" : "translateY(10px)",
488	      }}
489	    >
490	      <div className="flex items-center justify-between gap-3">
491	        <span className="text-[13px] font-semibold text-white">{row.feature}</span>
492	        <VerdictPill v={row.verdict} />
493	      </div>
494	      <p className="mt-1.5 text-[11px] leading-relaxed text-slate-500">{row.note}</p>
495	      <div className="mt-3 grid grid-cols-2 gap-2">
496	        <div
497	          className={`rounded-xl px-3 py-2 ${
498	            row.verdict === "win"
499	              ? "border border-accent-cyan/20 bg-accent-cyan/[0.05]"
500	              : "border border-white/[0.06] bg-white/[0.02]"
501	          }`}
502	        >
503	          <span
504	            className={`flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wide ${
505	              row.verdict === "win" ? "text-accent-cyan" : "text-slate-500"
506	            }`}
507	          >
508	            {row.verdict === "win" ? <IconCheck size={12} /> : null} Nxeon
509	          </span>
510	          <span className="mt-1 block text-[12px] font-medium text-slate-200">{row.nxeon}</span>
