/**
 * Shared types + score helper for the "vs" comparison template
 * (components/marketing/comparisontemplate/*). The template itself
 * (ComparisonTemplate.tsx) is competitor-agnostic: every live "Nxeon vs X" /
 * "X alternative" page supplies its own `ComparisonData` object (see the
 * per-competitor files in this directory, e.g. `digitalocean.ts`) and passes
 * it in as the `data` prop.
 *
 * Rows are grouped (pricing / specs / support / platform) exactly like the
 * live comparison surface (CompareTable + ComparePageLayout), and the verdict
 * is three-way on purpose:
 *
 *   - "win"   → a genuine Nxeon differentiator (cyan check on the Nxeon side).
 *   - "tie"   → an honest, even match (a neutral dash — no manufactured win).
 *   - "other" → the competitor is the better fit here, and we say so.
 *
 * A comparison that only ever "wins" reads as marketing and gets discounted by
 * readers and by AI assistants alike; crediting the competitor where they lead
 * is exactly what makes the wins believable. Reviews are ILLUSTRATIVE sample
 * content (same status as the live <Testimonials/>) — no fabricated counts, and
 * the real Trustpilot/HostAdvice/Google numbers come from <ReviewBadges/>.
 */

export type Verdict = "win" | "tie" | "other";

export type CompareRow = {
  /** The feature axis, e.g. "Automatic backups". */
  feature: string;
  /** Nxeon's value for this row. */
  nxeon: string;
  /** The competitor's value for this row. */
  other: string;
  /** "win" → Nxeon leads · "tie" → even · "other" → competitor leads. */
  verdict: Verdict;
  /** One-line, honest context shown under the feature. */
  note: string;
};

export type CompareGroup = {
  /** Section label, e.g. "Pricing & terms". */
  label: string;
  rows: CompareRow[];
};

export type SwitchReason = {
  icon: "shield" | "backup" | "support" | "bolt";
  title: string;
  body: string;
};

export type MiniReview = {
  id: string;
  quote: string;
  name: string;
  meta: string;
};

export type Faq = { q: string; a: string };

/** The competitor's identity — name, logo slug and a neutral one-liner. */
export type CompetitorIdentity = {
  name: string;
  /** Lower-case slug → real logo at /public/logos/<slug>.svg (drop-in convention). */
  slug: string;
  /** Neutral one-liner for how the competitor positions itself — used in the header. */
  kind: string;
};

/**
 * Everything ComparisonTemplate needs to render one "Nxeon vs X" page. Every
 * live comparison page owns one of these (see `./digitalocean.ts` etc.) built
 * from that page's own real, previously-published facts — no invented
 * competitor figures.
 */
export type ComparisonData = {
  competitor: CompetitorIdentity;
  compareGroups: CompareGroup[];
  switchReasons: SwitchReason[];
  chooseNxeon: string[];
  chooseOther: string[];
  reviews: MiniReview[];
  faq: Faq[];
  disclaimer: string;
};

/**
 * Honest three-way scoreboard, derived from the rows so the hero can never
 * drift from the table — and so the competitor's genuine wins are counted,
 * not hidden.
 */
export function deriveScore(compareGroups: CompareGroup[]) {
  const rows = compareGroups.flatMap((g) => g.rows);
  return {
    nxeonWins: rows.filter((r) => r.verdict === "win").length,
    ties: rows.filter((r) => r.verdict === "tie").length,
    otherWins: rows.filter((r) => r.verdict === "other").length,
    total: rows.length,
  };
}

