import type { Metadata } from "next";
import Link from "next/link";
import { ComparisonTemplate } from "@/components/marketing/comparisontemplate/ComparisonTemplate";
import { HOSTINGER_DATA } from "@/components/marketing/comparisontemplate/hostinger";
import { CompetitorLogo } from "@/components/marketing/CompetitorLogo";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { FaqJsonLd, ProductJsonLd } from "@/components/marketing/StructuredData";
import { getVpsPriceBand } from "@/lib/vps-price-band";
import { db } from "@/lib/db";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
const PATH = "/vps-vs-hostinger";

export const metadata: Metadata = {
  title: "Nxeon vs Hostinger — VPS comparison",
  description:
    "How Nxeon compares to Hostinger for VPS hosting: NVMe performance, game servers, dedicated IP options, domains, and who each one suits best.",
  alternates: { canonical: PATH },
  openGraph: {
    type: "article",
    title: "Nxeon vs Hostinger — VPS comparison",
    description:
      "NVMe performance, game servers, dedicated IPs and domains compared. An honest look at where each provider fits.",
    url: `${APP_URL}${PATH}`,
    images: [{ url: `${APP_URL}/logo.png` }],
  },
};

// Prices track the live catalogue — see lib/vps-price-band.ts.
export const dynamic = "force-dynamic";

export default async function VpsVsHostinger() {
  let fromLabel: string | undefined;
  let plans: Array<{ name: string; priceCents: number }> = [];
  try {
    const [band, planRows] = await Promise.all([
      getVpsPriceBand(),
      db.plan.findMany({
        where: { active: true },
        orderBy: { priceCents: "asc" },
        select: { name: true, priceCents: true },
      }),
    ]);
    fromLabel = band?.fromLabel;
    plans = planRows;
  } catch {
    /* DB unavailable — render without a price badge or Product schema */
  }

  return (
    <>
      <FaqJsonLd items={HOSTINGER_DATA.faq} />
      {plans.length > 0 ? <ProductJsonLd plans={plans} /> : null}
      <ComparisonTemplate
        data={HOSTINGER_DATA}
        nxeonLogo={<CompetitorLogo slug="nxeon" name="Nxeon" size={26} />}
        competitorLogo={<CompetitorLogo slug={HOSTINGER_DATA.competitor.slug} name={HOSTINGER_DATA.competitor.name} size={26} />}
        reviewBadges={<ReviewBadges />}
        fromLabel={fromLabel}
      />
      <div className="rail py-10 text-center">
        <p className="text-sm text-slate-400">
          Already decided?{" "}
          <Link href="/migrate-from-hostinger" className="font-medium text-brand-300 hover:text-brand-200">
            See exactly how we move you over free →
          </Link>
        </p>
      </div>
    </>
  );
}

