  alternates: { canonical: PATH },
  openGraph: {
    type: "article",
    title: "Nxeon vs Hetzner — a Hetzner alternative for Asia-Pacific",
    description:
      "NVMe on ZFS, game servers, APAC latency and all-in pricing compared. An honest look at where each provider fits.",
    url: `${APP_URL}${PATH}`,
    images: [{ url: `${APP_URL}/logo.png` }],
  },
};

// Every Nxeon price below is read live from the catalogue via getVpsPriceBand().
export const dynamic = "force-dynamic";

export default async function HetznerAlternative() {
  let fromLabel: string | undefined;
  let plans: Array<{ name: string; priceCents: number }> = [];
  try {
    const [band, planRows] = await Promise.all([
      getVpsPriceBand(),
      db.plan.findMany({
        where: { active: true },
        orderBy: { priceCents: "asc" },
        select: { name: true, priceCents: true },
      }),
    ]);
    fromLabel = band?.fromLabel;
    plans = planRows;
  } catch {
    /* DB unavailable — render without a price badge or Product schema */
  }

  return (
    <>
      <FaqJsonLd items={HETZNER_DATA.faq} />
      {plans.length > 0 ? <ProductJsonLd plans={plans} /> : null}
      <ComparisonTemplate
        data={HETZNER_DATA}
        nxeonLogo={<CompetitorLogo slug="nxeon" name="Nxeon" size={26} />}
        competitorLogo={<CompetitorLogo slug={HETZNER_DATA.competitor.slug} name={HETZNER_DATA.competitor.name} size={26} />}
        reviewBadges={<ReviewBadges />}
        fromLabel={fromLabel}
      />
    </>
  );
}

